"""Immutable AVL storage used by the branchable scheduler.

Roots are cheap snapshots.  Neither rotations nor updates modify shared nodes.
The rank index aggregates both resident populations and successful service counts.
"""


class Node:
    __slots__ = ('key', 'value', 'left', 'right', 'height')

    def __init__(self, key, value, left=None, right=None):
        self.key = key
        self.value = value
        self.left = left
        self.right = right
        self.height = 1 + max(left.height if left else 0,
                              right.height if right else 0)


def _balance(key, value, left, right):
    lh = left.height if left else 0
    rh = right.height if right else 0
    if lh > rh + 1:
        ll, lr = left.left, left.right
        if (ll.height if ll else 0) >= (lr.height if lr else 0):
            return Node(left.key, left.value, ll,
                        Node(key, value, lr, right))
        return Node(lr.key, lr.value,
                    Node(left.key, left.value, ll, lr.left),
                    Node(key, value, lr.right, right))
    if rh > lh + 1:
        rl, rr = right.left, right.right
        if (rr.height if rr else 0) >= (rl.height if rl else 0):
            return Node(right.key, right.value,
                        Node(key, value, left, rl), rr)
        return Node(rl.key, rl.value,
                    Node(key, value, left, rl.left),
                    Node(right.key, right.value, rl.right, rr))
    return Node(key, value, left, right)


def put(root, key, value):
    if root is None:
        return Node(key, value)
    if key < root.key:
        return _balance(root.key, root.value,
                        put(root.left, key, value), root.right)
    if key > root.key:
        return _balance(root.key, root.value,
                        root.left, put(root.right, key, value))
    return Node(key, value, root.left, root.right)


def get(root, key):
    while root is not None:
        if key < root.key:
            root = root.left
        elif key > root.key:
            root = root.right
        else:
            return root.value
    return None


def pop_min(root):
    """Return (removed node, new root), for a nonempty tree."""
    if root.left is None:
        return root, root.right
    found, left = pop_min(root.left)
    return found, _balance(root.key, root.value, left, root.right)


def pop_max(root):
    if root.right is None:
        return root, root.left
    found, right = pop_max(root.right)
    return found, _balance(root.key, root.value, root.left, right)


def erase(root, key):
    """Delete a key known to exist."""
    if key < root.key:
        return _balance(root.key, root.value,
                        erase(root.left, key), root.right)
    if key > root.key:
        return _balance(root.key, root.value,
                        root.left, erase(root.right, key))
    if root.left is None:
        return root.right
    if root.right is None:
        return root.left
    successor, right = pop_min(root.right)
    return _balance(successor.key, successor.value, root.left, right)


def items(root):
    stack = []
    while root is not None or stack:
        while root is not None:
            stack.append(root)
            root = root.left
        root = stack.pop()
        yield root.key, root.value
        root = root.right


def from_sorted(entries):
    """Build a map in linear time from an ordered sequence of (key,value)."""
    def build(lo, hi):
        if lo >= hi:
            return None
        mid = (lo + hi) // 2
        key, value = entries[mid]
        return Node(key, value, build(lo, mid), build(mid + 1, hi))
    return build(0, len(entries))


class RankNode:
    __slots__ = ('key', 'live', 'served', 'left', 'right', 'height',
                 'live_total', 'served_total')

    def __init__(self, key, live, served, left=None, right=None):
        self.key = key
        self.live = live
        self.served = served
        self.left = left
        self.right = right
        self.height = 1 + max(left.height if left else 0,
                              right.height if right else 0)
        self.live_total = live + (left.live_total if left else 0) + (right.live_total if right else 0)
        self.served_total = served + (left.served_total if left else 0) + (right.served_total if right else 0)


def _rank_balance(key, live, served, left, right):
    lh = left.height if left else 0
    rh = right.height if right else 0
    if lh > rh + 1:
        ll, lr = left.left, left.right
        if (ll.height if ll else 0) >= (lr.height if lr else 0):
            return RankNode(left.key, left.live, left.served, ll,
                            RankNode(key, live, served, lr, right))
        return RankNode(lr.key, lr.live, lr.served,
                        RankNode(left.key, left.live, left.served, ll, lr.left),
                        RankNode(key, live, served, lr.right, right))
    if rh > lh + 1:
        rl, rr = right.left, right.right
        if (rr.height if rr else 0) >= (rl.height if rl else 0):
            return RankNode(right.key, right.live, right.served,
                            RankNode(key, live, served, left, rl), rr)
        return RankNode(rl.key, rl.live, rl.served,
                        RankNode(key, live, served, left, rl.left),
                        RankNode(right.key, right.live, right.served, rl.right, rr))
    return RankNode(key, live, served, left, right)


def rank_add(root, key, live_delta, served_delta=0):
    # Zero-population ranks can remain: there are at most as many distinct
    # ranks on an active branch as enqueue commands in the entire request.
    if root is None:
        return RankNode(key, live_delta, served_delta)
    if key < root.key:
        return _rank_balance(root.key, root.live, root.served,
                             rank_add(root.left, key, live_delta, served_delta),
                             root.right)
    if key > root.key:
        return _rank_balance(root.key, root.live, root.served, root.left,
                             rank_add(root.right, key, live_delta, served_delta))
    return RankNode(key, root.live + live_delta, root.served + served_delta,
                    root.left, root.right)


def live_less(root, key):
    total = 0
    while root is not None:
        if key <= root.key:
            root = root.left
        else:
            total += root.live + (root.left.live_total if root.left else 0)
            root = root.right
    return total


def served_greater(root, key):
    total = 0
    while root is not None:
        if key >= root.key:
            root = root.right
        else:
            total += root.served + (root.right.served_total if root.right else 0)
            root = root.left
    return total
