"""Packet records are immutable, so queue roots can safely share them."""
from dataclasses import dataclass


@dataclass(frozen=True, slots=True)
class Pkt:
    pktid: int
    flowid: int
    length: int
    flow_size: int
    rank: int = 0
    ordinal: int = 0
    bank: int = 0
    lag_origin: int = 0

    @property
    def oid(self):
        return self.flowid

    @property
    def priority(self):
        return self.rank, self.ordinal
